import math

# Create a function to compute distance with different metrics
def chebyshev_dist(p1, p2):
    return max(abs(p1[0]-p2[0]), abs(p1[1]-p2[1]))

def manhattan_dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

def get_source_at(r, c, demo1_in):
    """What source is at this location in the final grid"""
    # sources are 1, 2, 6, 8 (stay unchanged)
    return demo1_in[r][c]

